do $$
begin
  if (select id from profiles where email = 'manish.kumar@hbplus.fit') is null then
    raise exception 'No profiles row for %  -- has Manish logged into the app yet?', 'manish.kumar@hbplus.fit';
  end if;
  if (select id from profiles where email = 'satya.choudhury@hbplus.fit') is null then
    raise exception 'No profiles row for %  -- has Satya logged into the app yet?', 'satya.choudhury@hbplus.fit';
  end if;
end $$;

