insert into content_requests (id, data, updated_at)
select
  r.id,
  jsonb_set(
    jsonb_set(
      r.data,
      '{ownerId}',
      to_jsonb(case r.data->>'pipeline'
        when 'Internal requirement' then resolved.manish_id::text
        when 'Organic'              then resolved.satya_id::text
        else r.data->>'ownerId'
      end)
    ),
    '{requesterId}',
    to_jsonb(case r.data->>'pipeline'
      when 'Internal requirement' then resolved.manish_id::text
      when 'Organic'              then resolved.satya_id::text
      else r.data->>'requesterId'
    end)
  ),
  now()
from raw_rows r, resolved
on conflict (id) do update set data = excluded.data, updated_at = excluded.updated_at;
